const r=require('./round-fixes.js');
const A=q=>r.verifiedRoundAnswer(r.normalizeQuestion(q),{});
const yes=[
['我可以直接報名當會員嗎','向您想加入'],['想入會去哪裡報名','向您想加入'],['我想當協會會員要找誰','向您想加入'],
['我不想當會員了要跟誰講','向您加入的協會'],['退會要跟誰說','向您加入的協會'],
['退會理事會不同意可以嗎','沒有規定會員退會要經'],['退會會長不給退怎麼辦','沒有規定會員退會要經'],
['會員的會員資格可以給別人嗎','沒有規定會籍可以轉讓'],['會員有幾種','沒有規定會員要分'],['協會會員分哪幾類','沒有規定會員要分'],
['會員有哪些權利跟義務','表決權'],['會員的權利義務是什麼','表決權'],
['搬離屏東還是會員嗎','沒有規定會員一定要設籍'],['會員搬家了還算會員嗎','沒有規定會員一定要設籍'],
['會員要出席大會嗎不去會怎樣','第42條'],['會員一定要去開大會嗎','第42條'],
['會員可以暫時休會嗎','沒有「會員休會」'],['可以保留會籍嗎','沒有「會員休會」'],
];
const no=['合作社社員可以暫時休會嗎','公會會員要去哪裡報名','理事一定要出席理事會嗎','會員退會會費可以退嗎','協會搬家要報縣府嗎','想加入協會要怎麼申請','會員被停權是什麼意思','會員資格可以轉讓嗎'];
let bad=0;
for(const [q,k] of yes){const x=A(q);if(!x||!x.direct||!(x.summary+x.title).includes(k)){console.error('FAIL',q,x&&x.title);bad++;}}
const pat=/向您想加入的協會申請，資格|向您加入的協會表示|查不到需經理事會|協會不讓會員退會|會員分幾種|會員的權利和義務|會員搬家到外縣市還是會員嗎|會員不去開大會|會員暫時休會/;
for(const q of no){const x=A(q);if(x&&typeof x==='object'&&pat.test(x.title)){console.error('OVERTRIGGER',q,x.title);bad++;}}
if(bad)throw new Error('patrol62 failed '+bad);console.log('ok');
